cd /workspace && python3 -c "
import sqlite3, json
conn = sqlite3.connect('world.db')

valid_cabins = {'economy', 'business', 'basic_economy'}
valid_statuses = {'available', 'on time', 'delayed', 'cancelled', 'landed', 'flying'}

cur = conn.execute(\"SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'\")
for row in cur.fetchall():
    dates = json.loads(row[1])
    modified = False
    for d, info in dates.items():
        # Fix status
        if info.get('status') not in valid_statuses:
            info['status'] = 'available'
            modified = True
        # Fix prices - remove non-standard cabin keys
        if 'prices' in info:
            bad_keys = [k for k in info['prices'] if k not in valid_cabins]
            for k in bad_keys:
                del info['prices'][k]
                modified = True
        # Fix available_seats - remove non-standard cabin keys
        if 'available_seats' in info:
            bad_keys = [k for k in info['available_seats'] if k not in valid_cabins]
            for k in bad_keys:
                del info['available_seats'][k]
                modified = True
        # Ensure available status has required fields
        if info.get('status') == 'available':
            if 'prices' not in info:
                info['prices'] = {'economy': 199, 'business': 499, 'basic_economy': 149}
                modified = True
            if 'available_seats' not in info:
                info['available_seats'] = {'economy': 50, 'business': 10, 'basic_economy': 30}
                modified = True
    if modified:
        conn.execute('UPDATE flights SET dates_json=? WHERE flight_id=?', (json.dumps(dates), row[0]))
        print(f'Fixed {row[0]}')

conn.commit()
conn.close()
print('Done')
"

